72	    input: content,
73	  }).trim();
74	}
75	
76	/**
77	 * Create a tree object from formatted entries.
78	 */
79	function gitMkTree(cwd: string, entries: string): string {
80	  return execFileSync("git", ["mktree"], {
81	    cwd,
82	    encoding: "utf-8",
83	    input: entries,
84	  }).trim();
85	}
86	
87	/**
88	 * Create a commit from a tree hash.
89	 */
90	function gitCommitTree(cwd: string, tree: string, message: string): string {
91	  return execFileSync("git", ["commit-tree", tree, "-m", message], {
92	    cwd,
93	    encoding: "utf-8",
94	  }).trim();
95	}
96	
97	// ─── Gitignore helpers ───────────────────────────────────────────────
98	
99	/**
100	 * Check if the gitignore content already has an entry for .agentrack.
101	 * Matches common patterns: /.agentrack/, .agentrack/, /.agentrack, .agentrack
102	 */
103	function gitignoreHasEntry(content: string): boolean {
104	  return content.split("\n").some((rawLine) => {
105	    const line = rawLine.trim();
106	    // Skip comments and empty lines
107	    if (!line || line.startsWith("#")) return false;
108	    return (
109	      line === "/.agentrack/" ||
110	      line === ".agentrack/" ||
111	      line === "/.agentrack" ||
112	      line === ".agentrack"
113	    );
114	  });
115	}
116	
117	/**
118	 * Ensure .gitignore has an entry for .agentrack.
119	 * Appends the entry if missing. Does NOT stage or commit.
120	 * Returns true if an entry was added.
121	 */
122	function ensureGitignoreEntry(cwd: string): boolean {
123	  const gitignorePath = join(cwd, ".gitignore");
124	  if (existsSync(gitignorePath)) {
125	    const content = readFileSync(gitignorePath, "utf-8");
126	    if (gitignoreHasEntry(content)) {
127	      return false;
128	    }
129	    // Append entry (ensure newline before if file doesn't end with one)
130	    const suffix = content.endsWith("\n") ? "" : "\n";
131	    writeFileSync(gitignorePath, `${content}${suffix}/.agentrack/\n`, "utf-8");
132	  } else {
133	    writeFileSync(gitignorePath, "/.agentrack/\n", "utf-8");
134	  }
135	  return true;
136	}
137	
138	// ─── Precondition checks ─────────────────────────────────────────────
139	
140	/**
141	 * Validate preconditions before worktree initialization.
142	 * Throws AgentrackError if any precondition fails.
143	 */
144	function checkPreconditions(cwd: string): void {
145	  // Must be inside a git repo
146	  if (!isGitRepo(cwd)) {
147	    throw new AgentrackError(
148	      ErrorCodes.NOT_A_GIT_REPO.result,
149	      "Not inside a git repository",
150	      ErrorCodes.NOT_A_GIT_REPO.exitCode,
151	    );
152	  }
153	
154	  // .agentrack must not exist as a non-worktree (legacy)
155	  const agentrackPath = join(cwd, WORKTREE_DIR);
156	  if (existsSync(agentrackPath)) {
157	    const stat = statSync(agentrackPath);
158	    if (!stat.isDirectory()) {
159	      throw new AgentrackError(
160	        ErrorCodes.MIGRATION_REQUIRED.result,
161	        ".agentrack exists but is not a directory. Remove it and re-run init.",
162	        ErrorCodes.MIGRATION_REQUIRED.exitCode,
163	      );
164	    }
165	    // Directory exists — if not a worktree, it's a legacy directory
166	    if (!isWorktreeInitialized(cwd)) {
167	      throw new AgentrackError(
168	        ErrorCodes.MIGRATION_REQUIRED.result,
169	        ".agentrack/ exists but is not a git worktree. Remove it manually and re-run init.",
170	        ErrorCodes.MIGRATION_REQUIRED.exitCode,
171	      );
172	    }
173	    // If it IS a valid worktree, caller should handle ALREADY_INITIALIZED
174	  }
175	
176	  // Must not be on the _agentrack branch
177	  const currentBranch = getCurrentBranch(cwd);
178	  if (currentBranch === WORKTREE_BRANCH) {
179	    throw new AgentrackError(
180	      ErrorCodes.INVALID_STATE.result,
181	      "Cannot init: currently on the _agentrack branch. Switch to a code branch first.",
182	      ErrorCodes.INVALID_STATE.exitCode,
183	    );
184	  }
185	}
186	
187	// ─── Public API ──────────────────────────────────────────────────────
188	
189	/**
190	 * Detect which init scenario applies: 'fresh' (no remote branch) or 'join' (remote branch exists).
191	 */
192	export function detectInitScenario(cwd: string): "fresh" | "join" {
193	  try {
194	    const result = gitExec(cwd, ["ls-remote", "--heads", "origin", WORKTREE_BRANCH]);
195	    return result.trim().length > 0 ? "join" : "fresh";
196	  } catch {
197	    // No remote or no connectivity → fresh
198	    return "fresh";
199	  }
200	}
201	
202	/**
203	 * Check if .agentrack/ is a valid git worktree for the _agentrack branch.
204	 */
205	export function isWorktreeInitialized(cwd: string): boolean {
206	  try {
207	    const worktreeList = gitExec(cwd, ["worktree", "list", "--porcelain"]);
208	    const normalizedCwd = resolve(cwd);
209	    const expectedPath = normalize(join(normalizedCwd, WORKTREE_DIR));
210	
211	    return worktreeList.split("\n").some((line) => {
212	      if (!line.startsWith("worktree ")) return false;
213	      const wtPath = line.slice("worktree ".length);
214	      return normalize(wtPath) === expectedPath;
215	    });
216	  } catch {
217	    return false;
218	  }
219	}
220	
221	/**
222	 * Scenario A: create orphan branch with initial data, push, mount worktree.
223	 * Uses git plumbing commands to avoid modifying the working tree.
224	 */
225	export function initFreshWorktree(cwd: string): WorktreeInitResult {
226	  // 1. Create blob objects for initial files
227	  const configBlob = gitHashObject(cwd, `${JSON.stringify(DEFAULT_CONFIG, null, 2)}\n`);
228	  const indexBlob = gitHashObject(cwd, `${JSON.stringify(DEFAULT_INDEX, null, 2)}\n`);
229	  const depsBlob = gitHashObject(cwd, `${JSON.stringify(DEFAULT_DEPENDENCIES, null, 2)}\n`);
230	  const usersBlob = gitHashObject(cwd, `${JSON.stringify(DEFAULT_USERS, null, 2)}\n`);
231	
232	  // 2. Create a tree object referencing these blobs
233	  const treeInput = [
234	    `100644 blob ${configBlob}\tconfig.json`,
235	    `100644 blob ${indexBlob}\tindex.json`,
236	    `100644 blob ${depsBlob}\tdependencies.json`,
237	    `100644 blob ${usersBlob}\tusers.json`,
238	  ].join("\n");
239	  const tree = gitMkTree(cwd, treeInput);
240	
241	  // 3. Create a commit from the tree
242	  const commit = gitCommitTree(cwd, tree, "init _agentrack branch");
243	
244	  // 4. Create the _agentrack branch ref
245	  try {
246	    gitExec(cwd, ["branch", WORKTREE_BRANCH, commit]);
247	  } catch (err: any) {
248	    // Branch might already exist from a failed previous attempt
249	    const stderr = (err.stderr as string) || err.message || "";
250	    if (stderr.includes("already exists")) {
251	      // Force-update the branch to our new commit
252	      gitExec(cwd, ["branch", "-f", WORKTREE_BRANCH, commit]);
253	    } else {
254	      throw new AgentrackError(
255	        ErrorCodes.INVALID_STATE.result,
256	        `Failed to create branch: ${stderr}`,
257	        ErrorCodes.INVALID_STATE.exitCode,
258	      );
259	    }
260	  }
261	
262	  // 5. Push to remote (if available)
263	  if (hasRemote(cwd)) {
264	    try {
265	      gitExec(cwd, ["push", "-u", "origin", WORKTREE_BRANCH]);
266	    } catch (pushErr: any) {
267	      const stderr = (pushErr.stderr as string) || pushErr.message || "";
268	      // If push fails because branch already exists remotely, fall back to join
269	      if (
270	        stderr.includes("already exists") ||
271	        stderr.includes("failed to push") ||
272	        stderr.includes("non-fast-forward")
273	      ) {
274	        return initJoinWorktree(cwd);
275	      }
276	      // Network or other errors — proceed with local branch only (warn implicitly)
277	    }
278	  }
279	
280	  // 6. Ensure .gitignore entry
281	  ensureGitignoreEntry(cwd);
282	
283	  // 7. Mount worktree
284	  try {
285	    gitExec(cwd, ["worktree", "add", WORKTREE_DIR, WORKTREE_BRANCH]);
286	  } catch (err: any) {
287	    const stderr = (err.stderr as string) || err.message || "";
288	    throw new AgentrackError(
289	      ErrorCodes.INVALID_STATE.result,
290	      `Failed to mount worktree: ${stderr}`,
291	      ErrorCodes.INVALID_STATE.exitCode,
292	    );
293	  }
294	
295	  return { scenario: "fresh", path: resolve(cwd, WORKTREE_DIR) };
296	}
297	
298	/**
299	 * Scenario B: fetch remote branch, create tracking branch, mount worktree.
300	 */
301	export function initJoinWorktree(cwd: string): WorktreeInitResult {
302	  // 1. Fetch the remote branch
303	  try {
304	    gitExec(cwd, ["fetch", "origin", WORKTREE_BRANCH]);
305	  } catch (err: any) {
306	    const stderr = (err.stderr as string) || err.message || "";
307	    throw new AgentrackError(
308	      ErrorCodes.INVALID_STATE.result,
309	      `Failed to fetch remote branch: ${stderr}`,
310	      ErrorCodes.INVALID_STATE.exitCode,
311	    );
312	  }
313	
314	  // 2. Create local tracking branch
315	  try {
316	    gitExec(cwd, ["branch", WORKTREE_BRANCH, `origin/${WORKTREE_BRANCH}`]);
317	  } catch {
318	    // Branch might already exist — force-update to remote ref
319	    try {
320	      gitExec(cwd, ["branch", "-f", WORKTREE_BRANCH, `origin/${WORKTREE_BRANCH}`]);
321	    } catch (err: any) {
322	      const stderr = (err.stderr as string) || err.message || "";
323	      throw new AgentrackError(
324	        ErrorCodes.INVALID_STATE.result,
325	        `Failed to create tracking branch: ${stderr}`,
326	        ErrorCodes.INVALID_STATE.exitCode,
327	      );
328	    }
329	  }
330	
331	  // 3. Ensure .gitignore entry
332	  ensureGitignoreEntry(cwd);
333	
334	  // 4. Mount worktree
335	  try {
336	    gitExec(cwd, ["worktree", "add", WORKTREE_DIR, WORKTREE_BRANCH]);
337	  } catch (err: any) {
338	    const stderr = (err.stderr as string) || err.message || "";
339	    throw new AgentrackError(
340	      ErrorCodes.INVALID_STATE.result,
341	      `Failed to mount worktree: ${stderr}`,
342	      ErrorCodes.INVALID_STATE.exitCode,
343	    );
344	  }
345	
346	  return { scenario: "join", path: resolve(cwd, WORKTREE_DIR) };
347	}
348	
349	/**
350	 * Initialize the agentrack worktree. Performs precondition checks, detects the
351	 * scenario, and delegates to the appropriate setup function.
352	 *
353	 * Returns the init result, or throws AgentrackError on failure.
354	 */
355	export function initWorktree(cwd: string): WorktreeInitResult {
356	  // Check if already initialized
357	  if (isWorktreeInitialized(cwd)) {
358	    return { scenario: "fresh", path: resolve(cwd, WORKTREE_DIR) };
359	  }
360	
361	  // Validate preconditions (throws on failure)
362	  checkPreconditions(cwd);
363	
364	  // Detect scenario and delegate
365	  const scenario = detectInitScenario(cwd);
366	  if (scenario === "fresh") {
367	    return initFreshWorktree(cwd);
368	  }
369	  return initJoinWorktree(cwd);
370	}
371	
372	/**
373	 * Stage all changes, auto-commit, and push to remote.
374	 */
375	export function pushWorktree(cwd: string, message?: string): WorktreeSyncResult {
376	  const worktreeDir = join(cwd, WORKTREE_DIR);
377	
378	  // Verify worktree is initialized
379	  if (!isWorktreeInitialized(cwd)) {
380	    throw new AgentrackError(
381	      ErrorCodes.NOT_INITIALIZED.result,
382	      "Agentrack not initialized. Run `agt init` first.",
383	      ErrorCodes.NOT_INITIALIZED.exitCode,
384	    );
385	  }
386	
387	  // Stage all changes
388	  gitExec(worktreeDir, ["add", "-A"]);
389	
390	  // Check for staged changes
391	  let hasStagedChanges = false;
392	  try {
393	    gitExec(worktreeDir, ["diff", "--cached", "--quiet"]);
394	    // Exit code 0 = no diff = no staged changes
395	  } catch {
396	    // Exit code 1 = there are staged changes
397	    hasStagedChanges = true;
398	  }
399	
400	  if (hasStagedChanges) {
401	    // Commit staged changes
402	    const commitMessage =
403	      message || `sync: ${new Date().toISOString()}`;
404	    try {
405	      gitExec(worktreeDir, ["commit", "-m", commitMessage]);
406	    } catch (err: any) {
407	      const stderr = (err.stderr as string) || err.message || "";
408	      throw new AgentrackError(
409	        ErrorCodes.PUSH_FAILED.result,
410	        `git commit failed: ${stderr}`,
411	        ErrorCodes.PUSH_FAILED.exitCode,
412	      );
413	    }
414	  }
415	
416	  // Check if there's anything to push
417	  let hasUnpushedCommits = false;
418	  try {
419	    const count = gitExec(worktreeDir, ["rev-list", "--count", "@{upstream}..HEAD"]).trim();
420	    hasUnpushedCommits = parseInt(count, 10) > 0;
421	  } catch {
422	    // No upstream set — means we need to push
423	    hasUnpushedCommits = true;
424	  }
425	
426	  if (!hasStagedChanges && !hasUnpushedCommits) {
427	    return { synced: false, message: "No changes to sync" };
428	  }
429	
430	  // Push to remote
431	  if (hasRemote(cwd)) {
432	    try {
433	      gitExec(worktreeDir, ["push"]);
434	    } catch (err: any) {
435	      const stderr = (err.stderr as string) || err.message || "";
436	      throw new AgentrackError(
437	        ErrorCodes.PUSH_FAILED.result,
438	        `git push failed: ${stderr}`,
439	        ErrorCodes.PUSH_FAILED.exitCode,
440	      );
441	    }
442	  }
443	
444	  return {
445	    synced: true,
446	    commitCount: hasStagedChanges ? 1 : 0,
447	  };
448	}
449	
450	/**
451	 * Pull latest from remote into the worktree.
452	 */
453	export function pullWorktree(cwd: string): WorktreePullResult {
454	  const worktreeDir = join(cwd, WORKTREE_DIR);
455	
456	  // Verify worktree is initialized
457	  if (!isWorktreeInitialized(cwd)) {
458	    throw new AgentrackError(
459	      ErrorCodes.NOT_INITIALIZED.result,
460	      "Agentrack not initialized. Run `agt init` first.",
461	      ErrorCodes.NOT_INITIALIZED.exitCode,
462	    );
463	  }
464	
465	  try {
466	    const output = gitExec(worktreeDir, ["pull"]);
467	    // "Already up to date." means no updates
468	    const updated = !output.includes("Already up to date");
469	    return { updated };
470	  } catch (err: any) {
471	    const stderr = (err.stderr as string) || err.message || "";
472	    throw new AgentrackError(
473	      ErrorCodes.PULL_FAILED.result,
474	      `git pull failed: ${stderr}`,
475	      ErrorCodes.PULL_FAILED.exitCode,
476	    );
477	  }
478	}
